var DIG=['零','一','二','三','四','五','六','七','八','九'];
var BIG=['','十','百','千'];
var SEC=['','万','亿','兆'];
function sectionToCN(n, top){
  if(n===0) return '';
  var ds=[]; var t=n; while(t>0){ds.unshift(t%10);t=Math.floor(t/10);}
  var len=ds.length; var s='';
  for(var i=0;i<len;i++){ var d=ds[i]; var pos=len-1-i;
    if(d===0){ if(s && s[s.length-1]!=='零') s+='零'; }
    else { if(top && pos===1 && d===1 && i===0) s+=BIG[pos]; else s+=DIG[d]+BIG[pos]; }
  }
  return s.replace(/零+$/,'');
}
function numToCN(num){
  if(num===0) return '零';
  var neg=num<0; num=Math.abs(Math.floor(num));
  var secs=[]; while(num>0){secs.unshift(num%10000);num=Math.floor(num/10000);}
  var out='';
  for(var i=0;i<secs.length;i++){ var sec=secs[i]; var str=sectionToCN(sec, i===0);
    if(str===''){ if(out && out[out.length-1]!=='零') out+='零'; continue; }
    out+=str; if(i<secs.length-1) out+=SEC[secs.length-1-i];
  }
  out=out.replace(/零+/g,'零').replace(/零$/,'');
  return (neg?'负':'')+out;
}
var UD=['零','壹','贰','叁','肆','伍','陆','柒','捌','玖'];
var UU=['','拾','佰','仟']; var USEC=['','万','亿'];
function secToRMB(n){ if(n===0)return ''; var ds=[];var t=n;while(t>0){ds.unshift(t%10);t=Math.floor(t/10);}var len=ds.length;var s='';
  for(var i=0;i<len;i++){var d=ds[i];var pos=len-1-i; if(d===0){if(s&&s[s.length-1]!=='零')s+='零';}else s+=UD[d]+UU[pos];} return s.replace(/零+$/,''); }
function intToRMB(n){ if(n===0)return '零'; var secs=[];while(n>0){secs.unshift(n%10000);n=Math.floor(n/10000);}var out='';
  for(var i=0;i<secs.length;i++){var sec=secs[i];var str=secToRMB(sec);if(str===''){if(out&&out[out.length-1]!=='零')out+='零';continue;}out+=str+USEC[secs.length-1-i];}
  out=out.replace(/零+/g,'零').replace(/零$/,''); return out; }
function toRMB(yuan){ if(yuan===0) return '零圆整'; var neg=yuan<0; yuan=Math.abs(yuan);
  var total=Math.round(yuan*100); var yp=Math.floor(total/100); var jiao=Math.floor((total%100)/10); var fen=total%10;
  var s=''; if(yp>0) s=intToRMB(yp)+'圆'; if(jiao>0) s+=UD[jiao]+'角'; else if(fen>0 && yp>0) s+='零'; if(fen>0) s+=UD[fen]+'分'; else if(yp>0 && jiao===0) s+='整';
  return (neg?'负':'')+s; }
var EXPORTS={numToCN:numToCN, toRMB:toRMB};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.NumberToChineseForgePure = EXPORTS; }
